CREATE TABLE ClientsMap (id INTEGER PRIMARY KEY AUTOINCREMENT, FIO TEXT, Phone TEXT, Adress Text, Primechanie TEXT, Blist TEXT ,date TEXT, aboutUs TEXT);
CREATE TABLE Stock (id INTEGER PRIMARY KEY AUTOINCREMENT, Naimenovanie TEXT, Kategoriya TEXT, Podkategoriya TEXT, Colour TEXT, Brand TEXT, Model TEXT,CountOf TEXT, Price TEXT, Napominanie TEXT, Photo TEXT, Primechanie TEXT, Photo2 TEXT, Photo3 TEXT);
